1	const PROCESSING_FEE = 5;
2	
3	const BASE_PREMIUM_BY_ITEM_TYPE = {
4	  sword: 100,
5	  amulet: 60,
6	  staff: 80,
7	  potion: 40,
8	  rune: 25,
9	  moonstone: 25,
10	} as const satisfies Record<string, number>;
11	
12	type InsurableItemType = keyof typeof BASE_PREMIUM_BY_ITEM_TYPE;
13	
14	const BLOCK_SIZE = 3;
15	
16	const BLOCK_BASE_PREMIUM = 60;
17	
18	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
19	
20	export type ScenarioResult = { premium: number };
21	
22	export type ScenarioOutcome = { results: ScenarioResult[] };
23	
24	type Item = { type: InsurableItemType };
25	
26	type Scenario = { steps: { items: Item[] }[] };
27	
28	// Adds the surcharge as a separate term rather than scaling by 1.1, because
29	// `100 * 1.1` is 115.00000000000001 in binary floating point.
30	const withFirstInsuranceSurcharge = (amount: number): number =>
31	  amount + amount * FIRST_INSURANCE_SURCHARGE_RATE;
32	
33	// Amounts are rounded in the MHPCO's favour: premiums (charged to the
34	// customer) round up.
35	const roundPremiumInMHPCOsFavour = (amount: number): number =>
36	  Math.ceil(amount);
37	
38	const countByItemType = (items: Item[]): Map<InsurableItemType, number> => {
39	  const counts = new Map<InsurableItemType, number>();
40	
41	  for (const item of items) {
42	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
43	  }
44	
45	  return counts;
46	};
47	
48	// Exactly 3 alike components form a building block at a special base premium.
49	const basePremiumForCount = (type: InsurableItemType, count: number): number =>
50	  count === BLOCK_SIZE
51	    ? BLOCK_BASE_PREMIUM
52	    : count * BASE_PREMIUM_BY_ITEM_TYPE[type];
53	
54	const quotePremium = (items: Item[]): number => {
55	  let basePremium = 0;
56	
57	  for (const [type, count] of countByItemType(items)) {
58	    basePremium += basePremiumForCount(type, count);
59	  }
60	
61	  return roundPremiumInMHPCOsFavour(
62	    withFirstInsuranceSurcharge(basePremium) + PROCESSING_FEE,
63	  );
64	};
65	
66	export const runScenario = (scenario: unknown): ScenarioOutcome => {
67	  const { steps } = scenario as Scenario;
68	
69	  const results = steps.map((step) => ({ premium: quotePremium(step.items) }));
70	
71	  return { results };
72	};
